(()=>{
'use strict';let data=null;const $=s=>document.querySelector(s),make=(tag,text,cls)=>{const el=document.createElement(tag);if(text)el.textContent=text;if(cls)el.className=cls;return el};
const status=t=>{$('#editor-status').textContent=t};
const valid=data=>data&&typeof data==='object'&&Array.isArray(data.houses)&&data.houses.length===4&&data.contacts&&data.brand&&data.houses.every(h=>/^[a-z]+$/.test(h.slug)&&h.name&&typeof h.description==='string'&&Number(h.guests)>0&&Array.isArray(h.busy)&&Array.isArray(h.free));
function render(){
 const root=$('#editor-fields');root.replaceChildren();
 function group(title){const card=make('section',null,'editor-card');card.append(make('h2',title));const grid=make('div',null,'editor-grid');card.append(grid);root.append(card);return grid;}
 function field(grid,title,obj,key,type='text',note=''){
  const label=make('label',title);const input=make(type==='textarea'||type==='lines'?'textarea':'input');if(type!=='textarea'&&type!=='lines')input.type=type;else input.rows=3;input.value=Array.isArray(obj[key])?obj[key].join(type==='lines'?'\n':', '):obj[key]??'';input.dataset.key=key;
  input.addEventListener('input',()=>{if(type==='lines'){obj[key]=input.value.split('\n').map(x=>x.trim()).filter(Boolean)}else if(['busy','free','gallery'].includes(key)){obj[key]=input.value.split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean)}else if(['priceWeekday','priceWeekend','guests'].includes(key)){obj[key]=input.value===''?null:Number(input.value)}else obj[key]=input.value;syncJSON()});label.append(input);if(note){const p=make('p',note);label.append(p)}grid.append(label);return input;
 }
 const brand=group('Первый экран и будни');field(brand,'Текст первого экрана',data.brand,'intro','textarea');field(brand,'Дополнение на первом экране',data.brand,'introExtra','textarea');field(brand,'Заголовок блока будней',data.weekday,'title');field(brand,'Описание отдыха в будни',data.weekday,'text','textarea');
 const contacts=group('Контакты и ссылки');[['Телефон для отображения','phone'],['Телефон для звонка (+7…)','phoneRaw'],['WhatsApp, только цифры','whatsapp'],['Ссылка на личный MAX','max'],['Ссылка на личный Telegram','telegram'],['Telegram-канал','channel'],['Instagram','instagram'],['Адрес','address'],['Ссылка на 2ГИС','map'],['Адрес iframe Яндекс Карты','mapEmbed']].forEach(([label,key])=>field(contacts,label,data.contacts,key));
 for(const house of data.houses){const g=group(`Дом «${house.name}»`);field(g,'Название',house,'name');field(g,'Краткая характеристика',house,'style');field(g,'Описание',house,'description','textarea');field(g,'Дополнительное описание',house,'descriptionExtra','textarea');field(g,'Цена в будни, ₽ (пусто = по запросу)',house,'priceWeekday','number');field(g,'Цена в выходные, ₽ (пусто = по запросу)',house,'priceWeekend','number');if(house.signature){field(g,'Заголовок особенности',house.signature,'title');field(g,'Описание особенности',house.signature,'text','textarea')}if(house.secondarySignature){field(g,'Заголовок второго блока',house.secondarySignature,'title');field(g,'Описание второго блока',house.secondarySignature,'text','textarea')}for(const block of house.amenityGroups||[]){field(g,'Название группы удобств',block,'title');field(g,'Удобства: по одному на строку',block,'items','lines')}field(g,'Фото обложки: имя файла без .webp',house,'cover','text','Используйте файл из /assets. Новую фотографию сначала добавьте на хостинг в формате WebP.');field(g,'Фотографии галереи',house,'gallery','textarea','Имена файлов без .webp, через запятую. Добавьте подготовленные изображения в папку assets.');field(g,'Занятые ночи, ГГГГ-ММ-ДД',house,'busy','textarea','Перечислите даты через запятую. Дата выезда не является занятой ночью.');field(g,'Подтверждённо свободные ночи',house,'free','textarea','Остальные даты останутся в статусе «Уточнить», а не «Свободно».');}
 const settings=group('Календарь и аналитика');field(settings,'Дата обновления занятости, ГГГГ-ММ-ДД',data,'availabilityUpdatedAt','date');field(settings,'Номер счётчика Яндекс Метрики',data.analytics,'yandexMetrikaId','text','Без номера аналитика не загружается. С номером загружается только после согласия посетителя.');syncJSON();
}
function syncJSON(){$('#editor-json').value=JSON.stringify(data,null,2)}
function normalize(){for(const h of data.houses){if(h.gallery!==undefined){if(!Array.isArray(h.gallery)||!h.gallery.every(name=>typeof name==='string'&&/^[a-z0-9][a-z0-9_-]{0,120}$/i.test(name)))throw new Error('Укажите имена фото без расширения, пробелов и пути к папке.');h.gallery=[...new Set(h.gallery)];}if(h.priceWeekday!==null&&(!Number.isFinite(h.priceWeekday)||h.priceWeekday<0))throw new Error('Цена должна быть положительным числом.');if(h.priceWeekend!==null&&(!Number.isFinite(h.priceWeekend)||h.priceWeekend<0))throw new Error('Цена выходного дня должна быть положительным числом.');for(const key of ['busy','free'])for(const d of h[key]){if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||Number.isNaN(Date.parse(d))||new Date(d+'T12:00:00').toISOString().slice(0,10)!==d)throw new Error(`Проверьте дату ${d} в доме «${h.name}».`)}if(h.busy.some(d=>h.free.includes(d)))throw new Error(`В доме «${h.name}» одна дата отмечена и занятой, и свободной.`);if(!/^[a-zA-Z0-9][a-zA-Z0-9_-]{0,120}$/.test(h.cover))throw new Error('В имени фото допустимы только латинские буквы, цифры и дефисы.');}if(!valid(data))throw new Error('Проверьте структуру данных.');}
function load(published){if(data)return;try{const draft=JSON.parse(localStorage.getItem('les-content-draft'));data=valid(draft)?draft:structuredClone(published);}catch{data=structuredClone(published)}render();status('Данные загружены. Локальный черновик не меняет опубликованный сайт.');}
window.addEventListener('les:content',e=>load(e.detail));if(window.lesContent)load(window.lesContent);
window.addEventListener('les:content-error',()=>status('Не удалось загрузить content.json. Проверьте соединение или импортируйте файл.'));
$('#editor-save').addEventListener('click',()=>{try{normalize();localStorage.setItem('les-content-draft',JSON.stringify(data));status('Черновик сохранён только в этом браузере. Для публикации скачайте content.json.');}catch(e){status(e.message)}});
fetch('/admin/status',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(result=>{if(!result?.authenticated)return;$('#editor-publish').hidden=false;const notice=$('.editor-notice');notice.querySelector('h2').textContent='Редактор сайта на этом компьютере';notice.querySelector('p').textContent='Меняйте данные и сохраняйте черновик для проверки. Кнопка «Сохранить на сайте» применит изменения к локальной версии сайта.'}).catch(()=>{});
$('#editor-publish')?.addEventListener('click',async()=>{const button=$('#editor-publish');try{normalize();button.disabled=true;status('Сохраняем и обновляем сайт…');const response=await fetch('/admin/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Не удалось сохранить.');localStorage.removeItem('les-content-draft');status('Изменения сохранены на сайте на этом компьютере. Обновите страницу сайта.');}catch(e){status(e.message)}finally{button.disabled=false}});
$('#editor-download').addEventListener('click',()=>{try{normalize();const blob=new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob);const a=make('a');a.href=url;a.download='content.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Файл скачан. Замените /content.json на хостинге, чтобы опубликовать правки.');}catch(e){status(e.message)}});
$('#editor-import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000){status('Файл слишком большой. Максимум 2 МБ.');return}try{const next=JSON.parse(await file.text());if(!valid(next))throw new Error('Неверная структура файла. Нужны четыре дома и блок контактов.');const prev=data;data=next;try{normalize()}catch(err){data=prev;throw err}render();status('Файл импортирован. Проверьте данные и сохраните черновик.');}catch(err){status(err.message)}finally{e.target.value=''}});
$('#editor-apply-json').addEventListener('click',()=>{try{const next=JSON.parse($('#editor-json').value);if(!valid(next))throw new Error('Проверьте структуру JSON.');const prev=data;data=next;try{normalize()}catch(err){data=prev;throw err}render();status('JSON применён. Сохраните черновик или скачайте файл.');}catch(err){status(err.message)}});
$('#editor-reset').addEventListener('click',()=>{try{localStorage.removeItem('les-content-draft');data=structuredClone(window.lesContent);render();status('Локальный черновик удалён. Загружены опубликованные данные.');}catch{status('Не удалось удалить черновик: браузер запретил доступ к локальному хранилищу.')}});
})();
